/**
 * Best-effort shallow PR checkout for hosts whose SDK agents should read the
 * reviewed repo instead of the host's own checkout.
 *
 * Returns `{ ok: false, reason }` when the PR's SCM has no clone support,
 * when no head SHA is pinned, when the target has no remote, when no clone
 * credential is available, or when the clone fails. Failures are logged,
 * never thrown.
 */
export async function tryCreateShallowPrCheckout(options) {
    const { prUrl, headSha, baseSha, headBranch, checkoutDir } = options;
    const target = options.target ?? (prUrl === undefined ? undefined : resolveScmCloneTarget(prUrl));
    if (target === undefined) {
        logShallowClone("skipped: unsupported SCM for shallow clone", { prUrl });
        return { ok: false, reason: "skipped: unsupported SCM for shallow clone" };
    }
    if (headSha === undefined) {
        logShallowClone("skipped: no pinned head SHA", {
            repo: target.repo,
            prUrl,
        });
        return { ok: false, reason: "skipped: no pinned head SHA" };
    }
    const auth = options.auth ?? defaultCloneAuth(target);
    if (auth === undefined) {
        let remoteUrl;
        try {
            remoteUrl = secretsOf(target).remoteUrl;
        }
        catch (error) {
            const reason = errorSummary(error);
            logShallowClone("failed; caller falls back to host checkout", {
                repo: target.repo,
                prNumber: target.prNumber,
                prUrl,
                error: reason,
            });
            return { ok: false, reason };
        }
        if (remoteUrl.startsWith("https://")) {
            // Fail fast instead of letting an unauthenticated fetch 404/hang: HTTPS
            // clones need the provider's credential (or an explicit token).
            logShallowClone("skipped: no clone credential", {
                repo: target.repo,
                provider: target.provider,
                prUrl,
            });
            return {
                ok: false,
                reason: `skipped: no ${target.provider} clone credential (pass auth.token, or set the provider token in the environment)`,
            };
        }
    }
    try {
        return {
            ok: true,
            checkout: await createShallowPrCheckout({
                target,
                headSha,
                baseSha,
                headBranch,
                checkoutDir,
                auth,
            }),
        };
    }
    catch (error) {
        const reason = errorSummary(error);
        logShallowClone("failed; caller falls back to host checkout", {
            repo: target.repo,
            prNumber: target.prNumber,
            headSha,
            error: reason,
        });
        return { ok: false, reason: `clone failed: ${reason}` };
    }
}
